// Cloudflare Worker entry: the Next.js app (built by OpenNext) plus the daily stock check.
// The cron trigger in wrangler.jsonc calls scheduled(), which calls the same route Vercel's cron used.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; SITE_URL?: string; NEXT_PUBLIC_SITE_URL?: string; NEXT_PUBLIC_SUPABASE_URL?: string; NEXT_PUBLIC_SUPABASE_ANON_KEY?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

// ---- "coming soon" mode -------------------------------------------------------------------------------
// While settings.public.launch.live is false, visitors on the real domain see /coming-soon instead of the shop.
// Staff areas, APIs, legal pages and files keep working there; the workers.dev address always shows the full
// shop (and is never indexed by search engines).
const PUBLIC_HOSTS = new Set(["greenland-afroasia.de", "www.greenland-afroasia.de"]);
const ALWAYS_OPEN = /^\/(admin|manager|steuerberater|api|_next|offer|coming-soon|legal|pdfjs|icons?|manifest|robots\.txt|sitemap|favicon|apple-icon)(\/|$|\.|-)|\.[a-z0-9]{2,5}$/i;
let launch = { live: true, at: 0 };

async function isLive(env: Env): Promise<boolean> {
  if (Date.now() - launch.at < 60_000) return launch.live;
  try {
    const r = await fetch(`${env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/settings?key=eq.public.launch&select=value`, {
      headers: { apikey: env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "", authorization: `Bearer ${env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? ""}` },
    });
    const rows = (await r.json()) as { value?: { live?: boolean } }[];
    launch = { live: rows?.[0]?.value?.live !== false, at: Date.now() };
  } catch {
    launch = { ...launch, at: Date.now() }; // keep the last known state for a minute
  }
  return launch.live;
}

export default {
  async fetch(req: Request, env: Env, ctx: Ctx) {
    const url = new URL(req.url);
    if (url.hostname.endsWith(".workers.dev")) {
      const res = await handler.fetch(req, env, ctx);
      const out = new Response(res.body, res);
      out.headers.set("X-Robots-Tag", "noindex, nofollow");
      return out;
    }
    if (PUBLIC_HOSTS.has(url.hostname) && !ALWAYS_OPEN.test(url.pathname) && !(await isLive(env))) {
      // same method and body, so the sign-up form (a server action posted to this URL) keeps working
      const res = await handler.fetch(new Request(new URL("/coming-soon", url), req), env, ctx);
      const out = new Response(res.body, { status: 200, headers: res.headers });
      out.headers.set("X-Robots-Tag", "noindex");
      out.headers.set("Cache-Control", "no-store");
      return out;
    }
    return handler.fetch(req, env, ctx);
  },
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    const url = new URL("/api/cron/low-stock", env.SITE_URL || env.NEXT_PUBLIC_SITE_URL || "https://greenland-store.workers.dev");
    const req = new Request(url, { headers: env.CRON_SECRET ? { authorization: `Bearer ${env.CRON_SECRET}` } : {} });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// Durable Object classes OpenNext may reference
// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
